var labelPairUniqueKeys = map[LabelPairUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	LabelPairUniqueById:          {`(id)`, `id = label_pair.id`, `SELECT "id", "first_id", "second_id" FROM label_pair WHERE (id) IN (%s)`, ``, []string{`id`}},
	LabelPairUniqueByFirstSecond: {`(first_id, second_id)`, `first_id = label_pair.first_id`, `SELECT "id", "first_id", "second_id" FROM label_pair WHERE (first_id, second_id) IN (%s)`, ``, []string{`first_id`, `second_id`}},
}

// labelPairKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func labelPairKeyOf(on LabelPairUniqueKey, row *types.LabelPair) (string, bool) {
	switch on {
	case LabelPairUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	case LabelPairUniqueByFirstSecond:
		return upsertKeyText(upsertKeyValue(row.First.Id, false), upsertKeyValue(row.Second.Id, false))
	}
	return "", false
}

